#!/usr/bin/env python3
"""
Test case showing a realistic use case where a plugin needs to access 
components during initialization.
"""

from apispec import APISpec, BasePlugin


class CustomPlugin(BasePlugin):
    """A plugin that wants to pre-register some common components during initialization"""

    def init_spec(self, spec):
        """Initialize plugin and register some default components"""
        super().init_spec(spec)

        # This plugin wants to register some default response components
        # that are commonly used across the API
        try:
            spec.components.response(
                "GenericError",
                {
                    "description": "Generic error response",
                    "content": {
                        "application/json": {
                            "schema": {
                                "type": "object",
                                "properties": {
                                    "error": {"type": "string"},
                                    "code": {"type": "integer"}
                                }
                            }
                        }
                    }
                }
            )

            spec.components.response(
                "UnauthorizedError", 
                {
                    "description": "Authentication required",
                    "content": {
                        "application/json": {
                            "schema": {
                                "type": "object", 
                                "properties": {
                                    "error": {"type": "string"}
                                }
                            }
                        }
                    }
                }
            )

            print("SUCCESS: Plugin registered default components during initialization")

        except AttributeError as e:
            print(f"FAILED: Cannot access components during init_spec: {e}")
            raise


def test_plugin_needing_components_access():
    """Test a realistic plugin that needs components access during initialization"""
    print("=== Testing Realistic Plugin Use Case ===")

    try:
        spec = APISpec(
            title="My API",
            version="1.0.0",
            openapi_version="3.0.2", 
            plugins=[CustomPlugin()],
        )

        # Check that the components were registered
        components_dict = spec.to_dict().get("components", {})
        responses = components_dict.get("responses", {})

        print(f"Registered responses: {list(responses.keys())}")

        if "GenericError" in responses and "UnauthorizedError" in responses:
            print("SUCCESS: Plugin successfully registered components")
            return True
        else:
            print("FAILED: Components not properly registered")
            return False

    except Exception as e:
        print(f"FAILED: {e}")
        return False


if __name__ == "__main__":
    success = test_plugin_needing_components_access()
    if success:
        print("\nPlugin use case works!")
    else:
        print("\nPlugin use case failed - this demonstrates the issue")

#!/usr/bin/env python3
"""
Test to ensure Components can still interact with plugins properly after our changes.
"""

from apispec import APISpec, BasePlugin


class SchemaHelperPlugin(BasePlugin):
    """Plugin that implements schema_helper to modify schemas"""

    def schema_helper(self, name, definition, **kwargs):
        # Add a common field to all schemas
        if name != "ModifiedSchema":  # Avoid infinite recursion
            definition.setdefault("properties", {})["added_by_plugin"] = {
                "type": "string",
                "description": "Field automatically added by plugin"
            }
        return definition


def test_components_plugin_interaction():
    """Test that Components still properly interacts with plugins"""
    print("=== Testing Components-Plugin Interaction ===")

    plugin = SchemaHelperPlugin()

    spec = APISpec(
        title="Test API",
        version="1.0.0", 
        openapi_version="3.0.2",
        plugins=[plugin],
    )

    # Add a schema - the plugin should modify it
    spec.components.schema(
        "TestSchema",
        {
            "type": "object",
            "properties": {
                "name": {"type": "string"}
            }
        }
    )

    # Check that the plugin's schema_helper was called
    spec_dict = spec.to_dict()
    schemas = spec_dict["components"]["schemas"]
    test_schema = schemas["TestSchema"]

    # The plugin should have added the "added_by_plugin" field
    assert "added_by_plugin" in test_schema["properties"], \
        "Plugin's schema_helper should have been called and modified the schema"

    print("✓ Components-plugin interaction works correctly")
    print(f"Schema properties: {list(test_schema['properties'].keys())}")
    return True


if __name__ == "__main__":
    success = test_components_plugin_interaction()
    if success:
        print("\n🎉 Plugin interaction test passed!")
    else:
        print("\n❌ Plugin interaction test failed!")

