"""
Test to verify that plugins can access APISpec.components in their init_spec method.
This test ensures the fix for the issue "Ability to access APISpec.components in plugin init_spec method" works.
"""

import pytest
from apispec import APISpec, BasePlugin


class ComponentsAccessPlugin(BasePlugin):
    """Plugin that tries to access spec.components in init_spec"""

    def __init__(self):
        super().__init__()
        self.accessed_components = False
        self.registered_default_components = False

    def init_spec(self, spec):
        super().init_spec(spec)
        try:
            # This should now work - accessing spec.components
            components = spec.components
            self.accessed_components = True

            # Test that we can actually use the components to register defaults
            spec.components.response(
                "DefaultError",
                {
                    "description": "Default error response",
                    "content": {
                        "application/json": {
                            "schema": {
                                "type": "object",
                                "properties": {
                                    "error": {"type": "string"}
                                }
                            }
                        }
                    }
                }
            )
            self.registered_default_components = True

        except AttributeError:
            self.accessed_components = False
            raise


def test_plugin_can_access_components_during_init():
    """Test that plugins can access spec.components in their init_spec method"""
    plugin = ComponentsAccessPlugin()

    spec = APISpec(
        title="Test API",
        version="1.0.0",
        openapi_version="3.0.2",
        plugins=[plugin],
    )

    # Verify the plugin could access components
    assert plugin.accessed_components is True, "Plugin should be able to access spec.components during init_spec"
    assert plugin.registered_default_components is True, "Plugin should be able to use components during init_spec"

    # Verify the component was actually registered
    spec_dict = spec.to_dict()
    responses = spec_dict.get("components", {}).get("responses", {})
    assert "DefaultError" in responses, "Plugin should have been able to register components during init"


def test_multiple_plugins_can_access_components():
    """Test that multiple plugins can all access components during init"""

    class Plugin1(BasePlugin):
        def init_spec(self, spec):
            super().init_spec(spec)
            spec.components.schema("Plugin1Schema", {"type": "object"})

    class Plugin2(BasePlugin):
        def init_spec(self, spec):
            super().init_spec(spec)
            spec.components.schema("Plugin2Schema", {"type": "object"})

    spec = APISpec(
        title="Test API",
        version="1.0.0",
        openapi_version="3.0.2",
        plugins=[Plugin1(), Plugin2()],
    )

    # Verify both schemas were registered
    spec_dict = spec.to_dict()
    schemas = spec_dict.get("components", {}).get("schemas", {})
    assert "Plugin1Schema" in schemas, "First plugin should access components"
    assert "Plugin2Schema" in schemas, "Second plugin should access components"


if __name__ == "__main__":
    test_plugin_can_access_components_during_init()
    test_multiple_plugins_can_access_components()
    print("All tests passed!")

