"""Comprehensive test to verify fixes and check for regressions"""

import jsonpatch

def test_edge_cases():
    """Test various edge cases to ensure no regressions"""

    print("=== Testing Edge Cases ===")

    # Test normal add operations still work
    try:
        result = jsonpatch.apply_patch({"foo": 1}, [{"op": "add", "path": "/bar", "value": 2}])
        assert result == {"foo": 1, "bar": 2}
        print("✓ Normal add operation works")
    except Exception as e:
        print(f"✗ Normal add operation failed: {e}")

    # Test normal array operations still work
    try:
        result = jsonpatch.apply_patch([1, 2], [{"op": "add", "path": "/1", "value": 1.5}])
        assert result == [1, 1.5, 2]
        print("✓ Normal array insert works")
    except Exception as e:
        print(f"✗ Normal array insert failed: {e}")

    # Test normal root replacement with replace operation
    try:
        result = jsonpatch.apply_patch({"foo": "bar"}, [{"op": "replace", "path": "", "value": {"baz": "qux"}}])
        assert result == {"baz": "qux"}
        print("✓ Normal root replace works")
    except Exception as e:
        print(f"✗ Normal root replace failed: {e}")

    # Test valid array indices still work
    test_cases = [
        ("0", True),
        ("1", True), 
        ("10", True),
        ("000", False),  # Should fail
        ("01", False),   # Should fail
        ("010", False),  # Should fail
    ]

    for index, should_pass in test_cases:
        try:
            # Test with array
            doc = ["a", "b", "c"]
            if int(index) < len(doc) if index.isdigit() and not (index.startswith('0') and len(index) > 1) else True:
                patch = [{"op": "test", "path": f"/{index}", "value": doc[int(index)] if index.isdigit() and not (index.startswith('0') and len(index) > 1) else "dummy"}]
                result = jsonpatch.apply_patch(doc, patch)
                if should_pass:
                    print(f"✓ Valid array index '{index}' works")
                else:
                    print(f"✗ Invalid array index '{index}' should have failed but didn't")
            else:
                # Skip test for out of bounds
                if should_pass:
                    print(f"✓ Array index '{index}' correctly rejected (out of bounds)")
        except jsonpatch.JsonPatchException:
            if not should_pass:
                print(f"✓ Invalid array index '{index}' correctly rejected")
            else:
                print(f"✗ Valid array index '{index}' incorrectly rejected")
        except Exception as e:
            print(f"? Array index '{index}' caused unexpected error: {e}")

    # Test that object keys that look like invalid array indices still work
    try:
        # Object with keys "00", "01" should work fine
        doc = {"00": "foo", "01": "bar"}
        result = jsonpatch.apply_patch(doc, [{"op": "test", "path": "/00", "value": "foo"}])
        print("✓ Object access with '00' key works")
    except Exception as e:
        print(f"✗ Object access with '00' key failed: {e}")

if __name__ == "__main__":
    test_edge_cases()

