    import re
    # Correct regex to match valid array indices (no leading zeros except for "0")
    valid_index_pattern = re.compile(r'^(?:0|[1-9][0-9]*)$')
    # Flawed regex from jsonpointer library that allows leading zeros
    flawed_pattern = re.compile('0|[1-9][0-9]*$')

    for part in self.pointer.parts:
        # Check if this part looks like it would be treated as an array index
        # by the flawed jsonpointer regex (digits only, would match the pattern)
        if isinstance(part, str) and part.isdigit() and flawed_pattern.match(part):
            # Validate it doesn't have leading zeros according to correct regex
