def _remove_artificial_attributes(self, element):
    """Remove artificial attributes that were added during parsing"""
    if hasattr(element.context, 'attrs') and element.context.attrs:
        # Remove any attribute that starts with our marker
        keys_to_remove = [key for key in element.context.attrs 
                        if key.lower().startswith('zpretty_newline_')]
        for key in keys_to_remove:
            del element.context.attrs[key]

    # Recursively process children
    for child in element.getchildren():
        self._remove_artificial_attributes(child)

