"""
Script to reproduce the issue with List and custom deserializer.
"""

from serde import serde, SerdeSkip
from serde.json import from_json
from dataclasses import dataclass
from typing import List


def des(cls, o):
    raise SerdeSkip()

@serde(deserializer=des)
@dataclass
class Foo:
    a: List[str]

def test_empty_list():
    """Test that empty list works"""
    result = from_json(Foo, '{"a": []}')
    print(f"Empty list result: {result}")
    assert result.a == []
    print("✓ Empty list test passed")

def test_non_empty_list():
    """Test that non-empty list fails with AttributeError"""
    try:
        result = from_json(Foo, '{"a": ["foo"]}')
        print(f"Non-empty list result: {result}")
        print("✓ Non-empty list test passed")
    except AttributeError as e:
        print(f"✗ Non-empty list test failed with AttributeError: {e}")
        raise
    except Exception as e:
        print(f"Non-empty list test failed with other exception: {e}")
        raise

if __name__ == "__main__":
    print("Testing issue reproduction...")
    test_empty_list()
    test_non_empty_list()

