"""
Test tuples to make sure the fix doesn't break them.
"""

from serde import serde, SerdeSkip
from serde.json import from_json
from dataclasses import dataclass
from typing import Tuple, List


def des(cls, o):
    raise SerdeSkip()

@serde(deserializer=des)
@dataclass
class FooTuple:
    a: Tuple[str, int]

@serde(deserializer=des) 
@dataclass
class FooTupleList:
    a: Tuple[List[str], int]

def test_tuples():
    """Test tuple functionality"""
    print("Testing tuple functionality...")

    # Basic tuple
    result = from_json(FooTuple, '{"a": ["hello", 42]}')
    print(f'Tuple result: {result}')
    assert result.a == ("hello", 42)

    # Tuple with list
    result = from_json(FooTupleList, '{"a": [["foo", "bar"], 42]}')
    print(f'Tuple with list result: {result}')
    assert result.a == (["foo", "bar"], 42)

    print("✅ Tuple functionality works correctly!")

if __name__ == "__main__":
    test_tuples()

