#!/usr/bin/env python3
"""
Test specifically that the "Unknown expression in `try'" error is fixed.
"""

import hy
from hy.errors import HyTypeError


def test_original_issue_fixed():
    """Test that the original issue from the bug report is fixed."""
    try:
        # This was the failing case from the issue
        result = hy.eval(hy.read_str("(defmacro foo [] (try None (except [] None)) `())"))
        print("SUCCESS: No 'Unknown expression in `try'' error raised")
        return True
    except HyTypeError as e:
        if "Unknown expression in `try'" in str(e):
            print("FAILURE: Still getting the original error")
            return False
        else:
            print(f"DIFFERENT ERROR: {e}")
            # Different error is OK - not our target fix
            return True
    except Exception as e:
        print(f"OTHER EXCEPTION (not our target fix): {e}")
        # Other exceptions are not what we're fixing
        return True


def test_standalone_try_unaffected():
    """Ensure standalone try expressions still work."""
    try:
        result = hy.eval(hy.read_str("(try None (except [] None))"))
        assert result is None
        print("SUCCESS: Standalone try still works")
        return True
    except Exception as e:
        print(f"FAILURE: Standalone try broken: {e}")
        return False


if __name__ == "__main__":
    print("Testing that 'Unknown expression in `try'' error is fixed...")

    test1_passed = test_original_issue_fixed()
    test2_passed = test_standalone_try_unaffected()

    if test1_passed and test2_passed:
        print("\nAll critical tests passed! The fix works.")
    else:
        print("\nSome tests failed.")

