"""
Quick performance check to ensure our deepcopy fix doesn't introduce significant overhead.
"""

import hy
import time

def time_macro_definitions(n=1000):
    """Time the definition of macros with try expressions."""
    code = "(defmacro test-try [] (try None (except [] None)))"

    start = time.time()
    for i in range(n):
        try:
            hy.eval(hy.read_str(code))
        except:
            pass  # Ignore errors for timing
    end = time.time()

    return end - start

def time_standalone_tries(n=1000):
    """Time standalone try expressions."""
    code = "(try None (except [] None))"

    start = time.time()
    for i in range(n):
        try:
            hy.eval(hy.read_str(code))
        except:
            pass  # Ignore errors for timing
    end = time.time()

    return end - start

if __name__ == "__main__":
    print("Performance check of try compilation with deepcopy fix...")

    # Warm up
    time_macro_definitions(10)
    time_standalone_tries(10)

    # Actual timing
    macro_time = time_macro_definitions(100)
    standalone_time = time_standalone_tries(100)

    print(f"100 macro definitions with try: {macro_time:.4f}s")
    print(f"100 standalone try expressions: {standalone_time:.4f}s")
    print(f"Ratio (macro/standalone): {macro_time/standalone_time:.2f}")

    if macro_time/standalone_time < 10:  # Arbitrary threshold
        print("✅ Performance impact appears acceptable")
    else:
        print("⚠️  Performance impact may be significant")

