#!/usr/bin/env python3
"""
Reproduction script for parser mode inheritance issue in jsonargparse.
"""

import inspect
import tempfile
import typing
from argparse import Namespace
from dataclasses import dataclass, field
from typing import Any, TypeVar

import jsonargparse
import yaml
from jsonargparse import ActionConfigFile, ArgumentParser, lazy_instance
from jsonargparse._loaders_dumpers import yaml_dump, yaml_load
from jsonargparse._util import import_object

_T = TypeVar('_T')

_VALUE_PATH = 'constant_path'


####################### Set up custom parser mode #######################


def is_constant_spec(value: Any) -> bool:
    is_constant = isinstance(value, (dict, Namespace)) and _VALUE_PATH in value
    if is_constant:
        allowed_keys = {
            _VALUE_PATH,
        }
        keys = getattr(value, "__dict__", value).keys()
        is_constant = len(set(keys) - allowed_keys) == 0
    return is_constant


def try_import_value(config: _T | dict[str, Any] | Namespace) -> _T | Any:
    if is_constant_spec(config):
        assert isinstance(config, (dict, Namespace))
        config = typing.cast(
            dict[str,
                 Any],
            getattr(config,
                    "__dict__",
                    config))
        return import_object(config[_VALUE_PATH])
    else:
        return config


def _yaml_constant_load(config: Any) -> Any:
    if is_constant_spec(config):
        return try_import_value(config)
    elif isinstance(config, (dict, Namespace)):
        config = typing.cast(
            dict[str,
                 Any],
            getattr(config,
                    "__dict__",
                    config))
        return {
            k: _yaml_constant_load(v) for k,
            v in config.items()
        }
