"""

import inspect
import tempfile
import typing
from argparse import Namespace
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Union

import jsonargparse
import yaml
from jsonargparse import ActionConfigFile, ArgumentParser, lazy_instance
from jsonargparse._loaders_dumpers import yaml_dump, yaml_load
from jsonargparse._util import import_object

# Custom loader/dumper setup
_VALUE_PATH = 'constant_path'

def is_constant_spec(value: Any) -> bool:
    is_constant = isinstance(value, (dict, Namespace)) and _VALUE_PATH in value
    if is_constant:
        allowed_keys = {_VALUE_PATH}
        keys = getattr(value, "__dict__", value).keys()
        is_constant = len(set(keys) - allowed_keys) == 0
    return is_constant

def _yaml_constant_load(config: Any) -> Any:
    if is_constant_spec(config):
        config = typing.cast(dict[str, Any], getattr(config, "__dict__", config))
        return import_object(config[_VALUE_PATH])
    elif isinstance(config, (dict, Namespace)):
        config = typing.cast(dict[str, Any], getattr(config, "__dict__", config))
        return {k: _yaml_constant_load(v) for k, v in config.items()}
    elif isinstance(config, (list, set, tuple)):
        return type(config)(_yaml_constant_load(v) for v in config)
    else:
        return config

def yaml_constant_load(stream: str) -> Any:
    value = yaml_load(stream)
    return _yaml_constant_load(value)

def _yaml_constant_dump(config: Any) -> Any:
    if inspect.isfunction(config):
        return {"constant_path": f"{config.__module__}.{config.__name__}"}
    elif isinstance(config, (dict, Namespace)):
        config = typing.cast(dict[str, Any], getattr(config, "__dict__", config))
        return {k: _yaml_constant_dump(v) for k, v in config.items()}
    elif isinstance(config, (list, set, tuple)):
        return type(config)(_yaml_constant_dump(v) for v in config)
    else:
        return config

def yaml_constant_dump(config: Any) -> str:
    config = _yaml_constant_dump(config)
    return typing.cast(str, yaml_dump(config))

jsonargparse.set_loader('constant_load', yaml_constant_load)
jsonargparse.set_dumper("constant_load", yaml_constant_dump)

# Test dataclasses
@dataclass
class InnerConfig:
    name: str = "default"
    function_ref: Optional[Any] = None
    params: Optional[Dict[str, Any]] = None

@dataclass
class MiddleConfig:
    items: List[InnerConfig] = field(default_factory=list)
    metadata: Optional[Dict[str, Any]] = None

@dataclass
class OuterConfig:
    middle: MiddleConfig = field(default_factory=MiddleConfig)
    settings: Optional[Dict[str, Any]] = None

# Test functions
def test_func_a(x: int) -> int:
    return x + 1

def test_func_b(y: str) -> str:
    return y.upper()

def test_nested_inheritance():
    """Test that deeply nested structures inherit parser mode correctly."""
    print("Testing nested parser mode inheritance...")

    parser = ArgumentParser(exit_on_error=False, parser_mode='constant_load')
    parser.add_argument("-c", "--config", action=ActionConfigFile)
    parser.add_class_arguments(OuterConfig, "config", sub_configs=True)

    # Create complex nested config with function references
    config_data = {
        "config": {
            "middle": {
                "items": [
                    {
                        "name": "item1",
                        "function_ref": {"constant_path": f"{__name__}.test_func_a"},
                        "params": {"multiplier": 2}
                    },
                    {
                        "name": "item2", 
                        "function_ref": {"constant_path": f"{__name__}.test_func_b"},
                        "params": {"prefix": "test_"}
                    }
                ],
                "metadata": {
                    "creator": "test",
                    "processor": {"constant_path": f"{__name__}.test_func_a"}
                }
            },
            "settings": {
                "handler": {"constant_path": f"{__name__}.test_func_b"},
                "debug": True
            }
        }
    }

    config_yaml = yaml.safe_dump(config_data)

    with tempfile.NamedTemporaryFile("w", suffix=".yaml", delete=False) as f:
        f.write(config_yaml)
        f.flush()

        # Parse the config
        cfg = parser.parse_args(["--config", f.name])

        # Dump the config - this should work now
        result = parser.dump(cfg, skip_none=False)
        print("SUCCESS: Complex nested config dumped successfully!")

        # Verify the dumped content contains expected function references
        assert "constant_path" in result
        assert f"{__name__}.test_func_a" in result
        assert f"{__name__}.test_func_b" in result

        print("All function references preserved correctly!")
        return True

def test_default_parser_mode():
    """Test that default parser mode still works."""
    print("Testing default parser mode compatibility...")

    @dataclass
    class SimpleConfig:
        name: str = "test"
        value: int = 42

    parser = ArgumentParser(exit_on_error=False)  # Default parser mode
    parser.add_class_arguments(SimpleConfig, "config")

