    with tempfile.NamedTemporaryFile("w", suffix=".yaml", delete=False) as f:
        f.write(config_yaml)
        f.flush()

        cfg = parser.parse_args(["--config", f.name])
        result = parser.dump(cfg)

        print("SUCCESS: Default parser mode works correctly!")
        return True

def main():
    try:
        success1 = test_nested_inheritance()
        success2 = test_default_parser_mode()

        if success1 and success2:
            print("\n✅ ALL TESTS PASSED! Parser mode inheritance is working correctly.")
            return True
        else:
            print("\n❌ Some tests failed.")
            return False

    except Exception as e:
        print(f"\n❌ Test failed with error: {e}")
        import traceback
        traceback.print_exc()
        return False

if __name__ == "__main__":
    success = main()
    exit(0 if success else 1)

