def _format_missing_data(self, df: pd.DataFrame) -> str:
    """Format missing data DataFrame for better readability."""
    if df.empty:
        return "No missing data"

    # Get all unique columns except model (which is dropped)
    columns = [col for col in df.columns if col != 'model']

    # If we have a simple case with few rows, return the original format
    if len(df) <= 10:
        return str(df.reset_index(drop=True))

    # For complex cases, provide a summary
    summary_lines = []

    # Group by variable if present
    if 'variable' in columns:
        for variable in df['variable'].unique():
            var_df = df[df['variable'] == variable]

            # Group by unit if present
            if 'unit' in columns:
                for unit in var_df['unit'].unique():
                    unit_df = var_df[var_df['unit'] == unit]
                    summary = self._summarize_missing_combinations(unit_df, columns)
                    summary_lines.append(f"Variable: {variable} (Unit: {unit})")
                    summary_lines.append(summary)
                    summary_lines.append("")
            else:
                summary = self._summarize_missing_combinations(var_df, columns)
                summary_lines.append(f"Variable: {variable}")
                summary_lines.append(summary)
                summary_lines.append("")
    else:
        summary = self._summarize_missing_combinations(df, columns)
        summary_lines.append(summary)

    return "\n".join(summary_lines)

def _summarize_missing_combinations(self, df: pd.DataFrame, columns: list) -> str:
    """Provide a concise summary of missing combinations."""
    # Convert year strings back to lists for analysis
    if 'year' in columns and not df.empty:
        # Parse year strings to lists
        year_sets = []
        for year_str in df['year']:
            if isinstance(year_str, str):
                years = year_str.split(',') if year_str else []
            elif pd.isna(year_str):
                years = []
            else:
                years = [str(year_str)]
            year_sets.append(set(years))

        # Find common patterns
        all_years = set()
        for year_set in year_sets:
            all_years.update(year_set)

        # Count how many times each year is missing
        year_counts = {}
        for year_set in year_sets:
            for year in year_set:
                year_counts[year] = year_counts.get(year, 0) + 1

        # Find most common year patterns
        if year_sets:
            # Most frequently missing years
            sorted_years = sorted(year_counts.items(), key=lambda x: x[1], reverse=True)
            top_years = [year for year, count in sorted_years[:10]]  # Top 10

            # Summary info
            total_combinations = len(df)
            unique_scenarios = df['scenario'].nunique() if 'scenario' in df.columns else 0
            unique_regions = df['region'].nunique() if 'region' in df.columns else 0

            summary_parts = []
            summary_parts.append(f"  Total missing combinations: {total_combinations}")
            if unique_scenarios:
                summary_parts.append(f"  Unique scenarios: {unique_scenarios}")
            if unique_regions:
                summary_parts.append(f"  Unique regions: {unique_regions}")

            if len(top_years) <= 10:
                summary_parts.append(f"  Missing years: [{', '.join(sorted(top_years))}]")
            else:
                summary_parts.append(f"  Missing years: [{', '.join(top_years[:5])}...] ({len(all_years)} total)")

            # Show some examples
            sample_size = min(5, len(df))
            if sample_size > 0:
                sample_rows = df.head(sample_size)[[col for col in columns if col != 'year']]
                summary_parts.append(f"  Sample missing entries:")
                for _, row in sample_rows.iterrows():
                    entry_parts = []
                    for col in sample_rows.columns:
                        entry_parts.append(f"{col}: {row[col]}")
                    summary_parts.append(f"    {', '.join(entry_parts)}")

            return "\n".join(summary_parts)

    # Fallback: return simplified original format for small dataframes
    if len(df) <= 20:
        return str(df.reset_index(drop=True))

    # For very large dataframes, show only summary
    summary_parts = [f"  Large number of missing combinations ({len(df)} total)"]

    # Show unique values for key dimensions
    for col in ['scenario', 'region']:
        if col in df.columns:
            unique_vals = sorted(df[col].unique())
            if len(unique_vals) <= 10:
                summary_parts.append(f"  {col.capitalize()}s: [{', '.join(map(str, unique_vals))}]")
            else:
                summary_parts.append(f"  {col.capitalize()}s: [{', '.join(map(str, unique_vals[:5]))}...] ({len(unique_vals)} total)")

    return "\n".join(summary_parts)

