#!/usr/bin/env python3

import sqlglot

def test_interval_functionality():
    """Test that regular INTERVAL expressions still work correctly."""

    # These should still work as INTERVAL expressions
    interval_cases = [
        # Standard INTERVAL usage
        "SELECT INTERVAL '5' DAY",
        "SELECT INTERVAL '10' HOUR + INTERVAL '30' MINUTE",
        "SELECT DATE_ADD(CURRENT_DATE, INTERVAL 1 MONTH)",
        "SELECT TIMESTAMP '2023-01-01' + INTERVAL '7' DAY",
    ]

    # Struct cases with INTERVAL should work now
    struct_cases = [
        "STRUCT<interval: DOUBLE>",
        "STRUCT<interval: DOUBLE COMMENT 'time interval'>",
        """CREATE TABLE test (col STRUCT<interval: DOUBLE>)""",
    ]

    print("=== Testing INTERVAL expressions (should still work) ===")
    for i, sql in enumerate(interval_cases):
        try:
            result = sqlglot.parse_one(sql, read="databricks")
            print(f"✓ INTERVAL case {i+1} passed: {result}")
        except Exception as e:
            print(f"✗ INTERVAL case {i+1} failed: {e}")

    print("\n=== Testing STRUCT with interval fields (should work now) ===")
    for i, sql in enumerate(struct_cases):
        try:
            result = sqlglot.parse_one(sql, read="databricks")
            print(f"✓ STRUCT case {i+1} passed: {result}")
        except Exception as e:
            print(f"✗ STRUCT case {i+1} failed: {e}")

if __name__ == "__main__":
    test_interval_functionality()

