from auth0.management.connections import Connections


class TestConnectionNameParameterEdgeCases(unittest.TestCase):

    @mock.patch("auth0.management.connections.RestClient")
    def test_empty_string_name(self, mock_rc):
        """Test that empty string name is handled correctly"""
        mock_instance = mock_rc.return_value
        mock_instance.get.return_value = {}

        c = Connections(domain="domain", token="jwttoken")
        c.all(name="")

        args, kwargs = mock_instance.get.call_args
        self.assertEqual(kwargs["params"]["name"], "")

    @mock.patch("auth0.management.connections.RestClient")
    def test_name_with_spaces(self, mock_rc):
        """Test that name with spaces works"""
        mock_instance = mock_rc.return_value
        mock_instance.get.return_value = {}

        c = Connections(domain="domain", token="jwttoken")
        c.all(name="My Connection Name")

        args, kwargs = mock_instance.get.call_args
        self.assertEqual(kwargs["params"]["name"], "My Connection Name")

    @mock.patch("auth0.management.connections.RestClient")
    def test_name_precedence_over_extra_params(self, mock_rc):
        """Test that explicit name parameter takes precedence over extra_params"""
        mock_instance = mock_rc.return_value
        mock_instance.get.return_value = {}

