#!/usr/bin/env python3

import sqlglot
from sqlglot import parse_one
from sqlglot.dialects.postgres import Postgres

def debug_parsing():
    """Debug the parsing flow to understand where it fails."""

    # Create a Postgres parser to debug step by step
    parser = Postgres.Parser()

    # Test 1: Parse a normal join (without parentheses)
    print("=== Test 1: Normal join ===")
    try:
        result = parse_one("select * from table1 left join table2 on 1 = 1;", read='postgres')
        print("SUCCESS:", result)
        print("FROM clause:", result.find(sqlglot.expressions.From))
        if result.find(sqlglot.expressions.From):
            print("FROM expressions:", result.find(sqlglot.expressions.From).expressions)
        joins = list(result.find_all(sqlglot.expressions.Join))
        print("Joins found:", len(joins))
        for i, join in enumerate(joins):
            print(f"  Join {i+1}: {join}")
    except Exception as e:
        print("ERROR:", e)

    print("\n=== Test 2: Parenthesized simple table ===") 
    try:
        result = parse_one("select * from (table1);", read='postgres')
        print("SUCCESS:", result)
        print("FROM clause:", result.find(sqlglot.expressions.From))
        if result.find(sqlglot.expressions.From):
            print("FROM expressions:", result.find(sqlglot.expressions.From).expressions)
    except Exception as e:
        print("ERROR:", e)

    print("\n=== Test 3: Parenthesized join (the failing case) ===")
    try:
        result = parse_one("select * from (table1 left join table2 on 1 = 1);", read='postgres')
        print("SUCCESS:", result)
    except Exception as e:
        print("ERROR:", e)

if __name__ == "__main__":
    debug_parsing()

