    # Mock the boto3 client to return a string template (like AWS actually does)
    mock_boto3_client_object = Mock()
    # AWS CloudFormation get_template returns TemplateBody as a string, not a dict
    mock_boto3_client_object.get_template.return_value = {
        "TemplateBody": '{"Resources": {"TestResource": {"Type": "AWS::S3::Bucket"}}}'
    }
    mock_boto3_client = Mock(return_value=mock_boto3_client_object)

    with patch('cfripper.main.Boto3Client', new=mock_boto3_client):
        try:
