        print(f"✓ Regular function: {url}")
    except NoReverseMatch as e:
        print(f"✗ Regular function failed: {e}")

    # Test 2: Function with numbers
    try:
        url = reverse("api-1.0.0:function123")
        print(f"✓ Function with numbers: {url}")
    except NoReverseMatch as e:
        print(f"✗ Function with numbers failed: {e}")

    # Test 3: Unicode function name
    try:
        url = reverse("api-1.0.0:αβγ_function")
        print(f"✓ Unicode function name: {url}")
    except NoReverseMatch as e:
        print(f"✗ Unicode function name failed: {e}")

    # Test 4: Nested function (might have qualified name)
    try:
        url = reverse("api-1.0.0:nested_function")
        print(f"✓ Nested function: {url}")
    except NoReverseMatch as e:
        print(f"✗ Nested function failed: {e}")
        # Check what the actual name might be
        import re
        nested_func_name = nested_func.__name__
        print(f"  Nested function actual name: {repr(nested_func_name)}")

    # Test 5: Lambda function (should NOT be resolvable)
    try:
        # Try common possibilities for lambda names
        possibilities = ['<lambda>', '_lambda_', 'lambda']
        resolved = False
        for possibility in possibilities:
            try:
                url = reverse(f"api-1.0.0:{possibility}")
                print(f"✗ Lambda unexpectedly resolvable as '{possibility}': {url}")
                resolved = True
                break
            except NoReverseMatch:
                continue
        if not resolved:
            print("✓ Lambda correctly has no resolvable URL name")
    except Exception as e:
        print(f"? Lambda test had unexpected error: {e}")

    print("\n" + "=" * 60)
    print("Edge case testing completed!")

if __name__ == "__main__":
    test_edge_cases()

