import jupytext

def test_comprehensive_scenarios():
    """Comprehensive test of the fix"""

    scenarios = [
        # Original issue - should preserve the magic format
        {
            'name': 'Python3 magic in python block',
            'input': '```python\n%%python3\na = 1\nprint(a)\n```\n',
            'expect_magic_preserved': True,
            'description': 'Original issue case'
        },

        # Direct language block - should remain unchanged
        {
            'name': 'Direct python3 block',
            'input': '```python3\na = 1\nprint(a)\n```\n',
            'expect_magic_preserved': False,
            'description': 'Should remain as python3 block'
        },

        # Other magics in python blocks
        {
            'name': 'Bash magic in python block',
            'input': '```python\n%%bash\necho hello\n```\n',
            'expect_magic_preserved': True,
            'description': 'Other magic should be preserved'
        },

        # Magic with arguments
        {
            'name': 'Magic with arguments',
            'input': '```python\n%%python3 --option\na = 1\n```\n',
            'expect_magic_preserved': True,
            'description': 'Magic with arguments should be preserved'
        },

        # Plain code - no changes expected
        {
            'name': 'Plain python code',
            'input': '```python\na = 1\nprint(a)\n```\n',
            'expect_magic_preserved': False,
            'description': 'Plain code should work normally'
        },

        # Multiple lines with magic
        {
            'name': 'Multiple lines with magic',
            'input': '```python\n%%python3\na = 1\nb = 2\nprint(a + b)\n```\n',
            'expect_magic_preserved': True,
            'description': 'Multi-line code with magic'
        }
    ]

    all_passed = True

    for scenario in scenarios:
        print(f"\n{'='*60}")
        print(f"Testing: {scenario['name']}")
        print(f"Description: {scenario['description']}")
        print("-" * 60)

        input_md = scenario['input']
        print("INPUT:")
        print(repr(input_md))

        try:
            # Parse to notebook
            nb = jupytext.reads(input_md, 'md')

            # Convert back to markdown
            output_md = jupytext.writes(nb, 'md')
            print("\nOUTPUT:")
            print(repr(output_md))

            # Check expectations
            has_magic_in_output = '%%python3' in output_md or '%%bash' in output_md

            if scenario['expect_magic_preserved']:
                if has_magic_in_output:
                    # Additional check: should be in python block, not python3 block
                    if output_md.startswith('```python\n%%'):
                        print("✅ PASS: Magic preserved in python block")
                    else:
                        print("⚠️  WARNING: Magic preserved but not in expected format")
                else:
                    print("❌ FAIL: Expected magic to be preserved but it was lost")
                    all_passed = False
            else:
                # For cases where we don't expect magic preservation
                if '%%python3' in input_md:
                    # This was originally a direct python3 block
                    if output_md.startswith('```python3'):
                        print("✅ PASS: Direct python3 block preserved")
                    else:
                        print("⚠️  INFO: Format changed but content equivalent")
                else:
                    print("✅ PASS: Non-magic case handled correctly")

            # Verify round-trip consistency
            nb2 = jupytext.reads(output_md, 'md')
            output2_md = jupytext.writes(nb2, 'md')

            if output_md == output2_md:
                print("🔄 Round-trip consistent")
            else:
                print("⚠️  Round-trip inconsistency detected")

        except Exception as e:
            print(f"❌ ERROR: {e}")
            all_passed = False

    print(f"\n{'='*60}")
    if all_passed:
        print("🎉 ALL SCENARIOS PASSED!")
    else:
        print("⚠️  Some scenarios had issues")

    return all_passed

if __name__ == '__main__':
    test_comprehensive_scenarios()

