#!/usr/bin/env python3

"""
Test to add to the test suite for the PyArrow __getitem__ fix
This test could be added to tests/frame/slice_test.py
"""

import pytest
import narwhals.stable.v1 as nw
from tests.utils import compare_dicts

def test_slice_single_column_integer_position(constructor_eager) -> None:
    """Test that df[:, integer] works for PyArrow backend."""
    data = {"x1": [0, 1, 2], "x2": [.1, .2, .3]}
    df = nw.from_native(constructor_eager(data), eager_only=True)

    # Test selecting second column (index 1) with slice for all rows
    result = df[:, 1]
    expected = {"x2": [.1, .2, .3]}

    # For series, we need to convert to dict for comparison
    result_dict = {result.name: result.to_list()}
    assert result_dict == expected

def test_slice_various_column_positions(constructor_eager) -> None:
    """Test various column position selections with slices."""  
    data = {"a": [1, 2, 3], "b": [4, 5, 6], "c": [7, 8, 9]}
    df = nw.from_native(constructor_eager(data), eager_only=True)

    # Test first column
    result = df[:, 0]
    expected = {"a": [1, 2, 3]}
    result_dict = {result.name: result.to_list()}
    assert result_dict == expected

    # Test middle column
    result = df[:, 1] 
    expected = {"b": [4, 5, 6]}
    result_dict = {result.name: result.to_list()}
    assert result_dict == expected

    # Test last column
    result = df[:, 2]
    expected = {"c": [7, 8, 9]}
    result_dict = {result.name: result.to_list()}
    assert result_dict == expected

if __name__ == "__main__":
    # Manual test
    import pandas as pd
    import polars as pl
    import pyarrow as pa

    constructors = [pd.DataFrame, pl.DataFrame, pa.table]

    for constructor in constructors:
        print(f"\nTesting with {constructor.__name__}")
        try:
            test_slice_single_column_integer_position(constructor)
            test_slice_various_column_positions(constructor)
            print("✅ PASSED")
        except Exception as e:
            print(f"❌ FAILED: {e}")

