"""

import narwhals as nw
import pyarrow as pa

data = {"x1": [0, 1, 2, 3, 4, 5], "x2": [.1, .2, .3, .4, .5, .6]}

@nw.narwhalify
def test_edge_cases(df):
    print("Testing edge cases...")

    # Test 1: Empty slice
    try:
        result = df[2:2, 1]
        print("✅ Empty slice [2:2, 1]:", list(result))
    except Exception as e:
        print("❌ Empty slice [2:2, 1]:", e)

    # Test 2: Slice beyond bounds
    try:
        result = df[10:20, 1]
        print("✅ Out of bounds slice [10:20, 1]:", list(result))
    except Exception as e:
        print("❌ Out of bounds slice [10:20, 1]:", e)

    # Test 3: Negative start
    try:
        result = df[-3:, 1]
        print("✅ Negative start [-3:, 1]:", list(result))
    except Exception as e:
        print("❌ Negative start [-3:, 1]:", e)

    # Test 4: Negative stop
    try:
        result = df[:-2, 1]
        print("✅ Negative stop [:-2, 1]:", list(result))
    except Exception as e:
        print("❌ Negative stop [:-2, 1]:", e)

    # Test 5: With step
