        result = df[1:5:2, 1]
        print("✅ With step [1:5:2, 1]:", list(result))
    except Exception as e:
        print("❌ With step [1:5:2, 1]:", e)

if __name__ == "__main__":
    test_edge_cases(pa.table(data))

