def check_plottable_dtype(obj):
    """
    Check that the data array contains plottable data types.
    """
    # These dtypes cannot be meaningfully plotted as numerical data
    non_plottable_dtypes = {
        'vector3', 'linear_transform3', 'affine_transform3', 
        'rotation3', 'translation3', 'string', 'datetime64', 'PyObject'
    }

    if str(obj.data.dtype) in non_plottable_dtypes:
        raise ValueError(
            f"Cannot plot data of dtype '{obj.data.dtype}'. "
            "This dtype does not represent scalar numerical data "
            "that can be plotted directly."
        )

def get_column_specification(self, column, **kwargs):
    colspec = self.preparer.format_column(column) + " " + \
        self.dialect.type_compiler.process(column.type)

    default = self.get_column_default_string(column)
    if default is not None:
        colspec += " DEFAULT " + default

    if column.computed is not None:
        colspec += " " + self.process(column.computed)

    if not column.nullable:
        colspec += " NOT NULL"

    return colspec

def visit_computed_column(self, generated, **kw):
    text = "GENERATED ALWAYS AS (%s)" % self.sql_compiler.process(
        generated.sqltext, include_table=False, literal_binds=True
    )
    if generated.persisted is True:
        text += " STORED"
    elif generated.persisted is False:
        text += " VIRTUAL"
    return text

